		_char_out(tls, statePtr, libc.Int32FromUint32(uint32((*TGIFState_t)(unsafe.Pointer(statePtr)).Fcur_accum&libc.Uint64FromInt32(0xff))))
		*(*uint64)(unsafe.Pointer(statePtr + 40088)) >>= uint64(8)
		*(*int32)(unsafe.Pointer(statePtr + 40096)) -= int32(8)
