	sv = libc.Int32FromUint8(*(*uint8)(unsafe.Pointer(st)))
	qe = Xjpeg_aritab[sv&int32(0x7F)] /* => Qe_Value */
	nl = libc.Uint8FromInt64(qe & int64(0xFF))
	qe >>= int64(8) /* Next_Index_LPS + Switch_MPS */
	nm = libc.Uint8FromInt64(qe & int64(0xFF))
	qe >>= int64(8) /* Next_Index_MPS */
