	*(*TJSAMPIMAGE)(unsafe.Pointer(mainp + 112 + 1*8)) = *(*TJSAMPIMAGE)(unsafe.Pointer(mainp + 112)) + uintptr((*Tjpeg_decompress_struct)(unsafe.Pointer(cinfo)).Fnum_components)*8
