		xbuf0 = *(*TJSAMPARRAY)(unsafe.Pointer(*(*TJSAMPIMAGE)(unsafe.Pointer(mainp + 112)) + uintptr(ci)*8))
		xbuf1 = *(*TJSAMPARRAY)(unsafe.Pointer(*(*TJSAMPIMAGE)(unsafe.Pointer(mainp + 112 + 1*8)) + uintptr(ci)*8))
