			/* calculate new total_colors if Ncolors[j] is incremented */
			temp = int64(total_colors / *(*int32)(unsafe.Pointer(Ncolors + uintptr(j)*4)))
			temp *= int64(*(*int32)(unsafe.Pointer(Ncolors + uintptr(j)*4)) + int32(1)) /* done in long arith to avoid oflo */
