// C documentation
//
//	/* Set the action on getting a CRC error for an ancillary or critical chunk. */
func Xpng_set_crc_action(tls *libc.TLS, png_ptr Tpng_structrp, crit_action int32, ancil_action int32) {
	if png_ptr == libc.UintptrFromInt32(0) {
		return
	}
	/* Tell libpng how we react to CRC errors in critical chunks */
	switch crit_action {
	case int32(PNG_CRC_NO_CHANGE): /* Leave setting as is */
	case int32(PNG_CRC_WARN_USE): /* Warn/use data */
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0400) | libc.Uint32FromUint32(0x0800))
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) |= uint32(0x0400)
	case int32(PNG_CRC_QUIET_USE): /* Quiet/use data */
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0400) | libc.Uint32FromUint32(0x0800))
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) |= libc.Uint32FromUint32(0x0400) | libc.Uint32FromUint32(0x0800)
	case int32(PNG_CRC_WARN_DISCARD): /* Not a valid action for critical data */
		Xpng_warning(tls, png_ptr, __ccgo_ts+15023)
		/* FALLTHROUGH */
		fallthrough
	case int32(PNG_CRC_ERROR_QUIT): /* Error/quit */
		fallthrough
	case PNG_CRC_DEFAULT:
		fallthrough
	default:
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0400) | libc.Uint32FromUint32(0x0800))
		break
	}
	/* Tell libpng how we react to CRC errors in ancillary chunks */
	switch ancil_action {
	case int32(PNG_CRC_NO_CHANGE): /* Leave setting as is */
	case int32(PNG_CRC_WARN_USE): /* Warn/use data */
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0100) | libc.Uint32FromUint32(0x0200))
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) |= uint32(0x0100)
	case int32(PNG_CRC_QUIET_USE): /* Quiet/use data */
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0100) | libc.Uint32FromUint32(0x0200))
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) |= libc.Uint32FromUint32(0x0100) | libc.Uint32FromUint32(0x0200)
	case int32(PNG_CRC_ERROR_QUIT): /* Error/quit */
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0100) | libc.Uint32FromUint32(0x0200))
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) |= uint32(0x0200)
	case int32(PNG_CRC_WARN_DISCARD): /* Warn/discard data */
		fallthrough
	case PNG_CRC_DEFAULT:
		fallthrough
	default:
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^(libc.Uint32FromUint32(0x0100) | libc.Uint32FromUint32(0x0200))
		break
	}
}

