		compose = int32(1)
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 764)) &= ^libc.Uint32FromUint32(0x800000)
		*(*Tpng_uint_32)(unsafe.Pointer(png_ptr + 760)) &= ^libc.Uint32FromUint32(0x2000)
